pass.answer:
#!/usr/bin/env bash
set -euo pipefail
curl() { printf '%s\n' "$*"; }
export -f curl
out="$(bash scripts/fetch-status.sh https://example.invalid)"
[[ "$out" == "--silent --max-time 5 https://example.invalid/status" ]] || { echo "FAIL: curl arguments changed: $out"; exit 1; }
echo PASS

